'use strict';
const $=s=>document.querySelector(s);
const iconPaths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',food:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M17 3c-3 4-3 8 0 8h3M20 3v18"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 19 0Z"/><path d="M7 10h9M7 14h6"/>',chart:'<path d="M4 20V10h4v10M10 20V4h4v16M16 20v-8h4v8"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L20 6"/>',water:'<path d="M12 2C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-13Z"/><path d="M9 15a3 3 0 0 0 3 3"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m10 9 3-2 3 5 4 1M12 9l-2 6-5 5M10 15l5 2 1 5M10 9l-4 4"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',send:'<path d="m3 3 19 9-19 9 3-9-3-9ZM6 12h16"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',crown:'<path d="m3 6 5 5 4-7 4 7 5-5-2 13H5Z"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 3v7h7"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',heart:'<path d="M20 5c-3-3-7 0-8 2-1-2-5-5-8-2-5 5 4 12 8 15 4-3 13-10 8-15Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',leaf:'<path d="M20 3C10 2 3 5 4 13c1 8 12 8 15 0 1-3 1-7 1-10ZM5 19 16 8"/>'};
const ic=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[n]||iconPaths.spark}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const foods=[
 {id:'adobo',name:'Chicken adobo',emoji:'🍗',serving:'1 serving · 150 g',kcal:310,sodium:720,sugar:3,protein:27,price:65,cat:'Ulam'},
 {id:'sinigang',name:'Sinigang na bangus',emoji:'🍲',serving:'1 bowl · 250 g',kcal:220,sodium:640,sugar:4,protein:24,price:70,cat:'Ulam'},
 {id:'rice',name:'Steamed rice',emoji:'🍚',serving:'1 cup · 158 g',kcal:205,sodium:2,sugar:0,protein:4,price:15,cat:'Sides'},
 {id:'monggo',name:'Ginisang monggo',emoji:'🥣',serving:'1 bowl · 200 g',kcal:210,sodium:380,sugar:3,protein:12,price:40,cat:'Ulam'},
 {id:'pancit',name:'Pancit canton',emoji:'🍜',serving:'1 plate · 200 g',kcal:380,sodium:950,sugar:5,protein:10,price:55,cat:'Ulam'},
 {id:'banana',name:'Saging na saba',emoji:'🍌',serving:'1 medium · 100 g',kcal:90,sodium:1,sugar:12,protein:1,price:10,cat:'Snacks'},
 {id:'coffee',name:'Sweetened coffee',emoji:'☕',serving:'1 cup · 240 ml',kcal:110,sodium:60,sugar:18,protein:2,price:20,cat:'Drinks'},
 {id:'pinakbet',name:'Pinakbet',emoji:'🥬',serving:'1 serving · 180 g',kcal:150,sodium:460,sugar:6,protein:6,price:45,cat:'Ulam'}
];
const initial=()=>({version:1,name:'Maria',budget:100,time:20,preferred:'Dancing',goal:'Build consistent habits',water:4,activity:10,platinum:true,coach:{name:'Kai',avatar:'🌿',tone:'Friendly',language:'English',length:'Short',vibe:false,avatarImage:'',persona:'Wellness companion',customPrompt:'',connection:{provider:'demo',url:'',model:'',temperature:0.7,maxTokens:500,live:false},instructions:'Suggest affordable Filipino food. Encourage me without lecturing.'},meals:[{uid:'breakfast',name:'Oats with banana',emoji:'🥣',portion:1,kcal:320,sodium:210,sugar:10,protein:9,meal:'Breakfast'}],activities:[{name:'Morning walk',minutes:10}],plan:[{id:'lunch',time:'12:30',kind:'meal',emoji:'🍗',title:'Chicken adobo + rice',detail:'A familiar lunch · around ₱80',done:false},{id:'move',time:'17:00',kind:'activity',emoji:'💃',title:'Dance break',detail:'20 minutes · at your own pace',minutes:20,done:false}],messages:[]});
let state;
try{const saved=loadKaincheckState();state=saved?.version===1?{...initial(),...saved,coach:{...initial().coach,...saved.coach}}:initial();if(!Array.isArray(state.meals)||!Array.isArray(state.messages)||!Array.isArray(state.plan))state=initial();}catch{state=initial();}
let screen='today',filter='All',query='',selectedFood=null,portion=1,activityChoice='Walking',settingsDraft=null,activeModal='',lastFocus=null,chatBusy=false,resetEpoch=0;
const save=()=>{if(!state.coachProfiles)initializeCoachProfiles();persistActiveCoach();try{persistKaincheckState(state);}catch{}};
const totals=()=>state.meals.reduce((a,m)=>{for(const k of ['kcal','sodium','sugar','protein'])a[k]+=Number(m[k]||0);return a;},{kcal:0,sodium:0,sugar:0,protein:0});
const tier=()=>`<span class="tier">${ic('crown')} ${state.platinum?'Platinum ++':'Free'}</span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2500);}
function header(){return `<div class="app-header"><a class="app-brand" href="#today"><span>✦</span>KainCheck</a><div class="header-actions">${kaincheckInstallButton()}<button class="avatar-btn" data-action="profile" aria-label="Open your profile">${userAvatar()}</button></div></div>`;}
function title(t,sub=''){return `<div class="topline"><h1 class="page-title">${t}</h1>${tier()}</div>${sub?`<p class="subtle" style="margin-top:9px">${sub}</p>`:''}`;}
function nav(){const items=[['today','home','Today'],['food','food','Food'],['coach','chat','Coach'],['progress','chart','Progress'],['profile','user','You']];$('#nav').innerHTML=items.map(([id,icon,label])=>`<button data-nav="${id}" class="${screen===id?'active':''}" ${screen===id?'aria-current="page"':''}>${ic(icon)}${label}</button>`).join('');}
function schedule(compact=false){return state.plan.map(p=>`<div class="schedule-item"><span class="time">${esc(p.time)}</span><span class="event-emoji">${p.emoji}</span><div class="event"><strong>${esc(p.title)}</strong><small>${esc(p.detail)}</small>${compact?'':`<div class="row-actions"><button data-edit-plan="${p.id}">Edit time</button><button data-swap-plan="${p.id}">${p.kind==='meal'?'Swap meal':'Change activity'}</button></div>`}</div><button class="check-btn ${p.done?'done':''}" data-complete="${p.id}" aria-label="${p.done?'Completed':'Complete'} ${esc(p.title)}" ${p.done?'disabled':''}>${p.done?ic('check'):''}</button></div>`).join('');}
function today(){const t=totals(),ratio=Math.min(100,Math.round(t.kcal/1800*100));return `<section class="screen">${header()}<p class="greeting">A fresh start, ${esc(state.name)} 🌤️</p>${title('Your day, in balance')}<div class="today-hero"><div class="hero-top"><div><p class="hero-small">Your food today</p><div class="hero-number">${t.kcal.toLocaleString()} <span>/ 1,800 kcal</span></div><p class="hero-detail">${state.meals.length} ${state.meals.length===1?'meal':'meals'} logged. Keep it simple.</p></div><div class="ring" style="--ring:${ratio}%"><span>${ratio}%</span></div></div><div class="nutrient-row"><div><b>${t.protein} g</b><small>Protein</small></div><div><b>${t.sodium.toLocaleString()} mg</b><small>Sodium</small></div><div><b>${t.sugar} g</b><small>Total sugar</small></div></div></div>${photoCheckerBanner()}<div class="quick-actions"><button data-action="food">${ic('plus')}Log a meal</button><button data-action="activity">${ic('walk')}Add movement</button><button data-action="plan">${ic('calendar')}Plan my day</button></div><button class="coach-prompt" data-action="coach"><span class="coach-face">${coachAvatar()}</span><div><strong>A little help from ${esc(state.coach.name)}</strong><p>${state.coach.vibe?'Good habits. Good vibes. Your next move?':'What fits your budget and your day?'}</p></div>${ic('arrow')}</button><div class="section-top"><h2>Your daily plan</h2><button class="text-btn" data-action="daily-plan">View & edit</button></div>${schedule(true)}<div class="section-top"><h2>Small wins count</h2></div><div class="habits"><div class="habit"><div class="habit-top">${ic('water')}<button class="plus-mini" data-action="water" aria-label="Add a glass of water">+</button></div><b>${state.water}<span style="font-size:11px;color:var(--muted);font-weight:400"> / 8 glasses</span></b><small>Stay refreshed</small></div><button class="habit" data-action="activity" style="text-align:left"><div class="habit-top">${ic('walk')}${ic('arrow')}</div><b>${state.activity} <span style="font-size:11px;font-weight:400">min</span></b><small>Movement today</small></button></div>${state.coach.vibe?`<div class="cheer"><b>✨ Vibe check: showing up</b><p>You opened the app. The wellness side quest has officially begun.</p></div>`:''}<p class="tiny-note">Demo day. Nutrition and prices are illustrative estimates. The 1,800 kcal figure is an example target.</p></section>`;}
function foodList(){return foods.filter(f=>(filter==='All'||f.cat===filter)&&f.name.toLowerCase().includes(query.toLowerCase())).map(f=>`<button class="food-row" data-food="${f.id}"><span class="food-art">${f.emoji}</span><span class="food-info"><strong>${f.name}</strong><small>${f.serving}<br>${f.kcal} kcal · ${f.protein} g protein</small></span><span class="food-plus">+</span></button>`).join('')||'<div class="empty">No dishes found.<br>Try “adobo”, “rice” or “monggo”.</div>';}
function food(){return `<section class="screen">${header()}${title('Familiar food, easy logging')}<p class="subtle" style="margin-top:10px">Your everyday Filipino dishes, in a few taps.</p>${photoCheckerBanner()}<label class="searchbox">${ic('search')}<input id="food-search" type="search" placeholder="Search Filipino food" aria-label="Search Filipino food" value="${esc(query)}"></label><div class="filters">${['All','Ulam','Sides','Snacks','Drinks'].map(f=>`<button class="chip ${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><div id="food-list">${foodList()}</div><div class="section-top"><h2>Logged today</h2><span class="subtle">${state.meals.length} entries</span></div>${state.meals.map(m=>`<div class="meal-log"><div class="event-emoji">${m.emoji}</div><span>${esc(m.name)}<small>${esc(m.meal)} · ${m.kcal} kcal · ${m.portion} serving${m.portion===1?'':'s'}</small></span><button class="delete-btn" data-delete-meal="${m.uid}" aria-label="Remove ${esc(m.name)}">${ic('trash')}</button></div>`).join('')||'<div class="empty">Your food log is ready for the first meal.</div>'}<p class="tiny-note">Example food entries for the prototype. Recipes and portions affect estimates.</p></section>`;}
function baseFirstMessage(){return state.coach.language==='Taglish'?`Hi ${state.name}! Si ${state.coach.name} ito. Anong budget at free time mo today? Gawa tayo ng plan na bagay sa ’yo. 🌿`:`Hi ${state.name}, I’m ${state.coach.name}. What does your day look like? Tell me your budget and free time, and we’ll make a plan that fits. 🌿`;}
function firstMessage(){const greeting=state.coachType==='custom'?state.coach.character?.greeting:BUILTIN_COACHES[state.coach.templateId||'kai']?.greeting;return greeting?replaceNames(greeting):applyPersona(baseFirstMessage());}
function coach(){return `<section class="coach-screen"><div class="coach-header"><div class="coach-face">${coachAvatar()}</div><div><h1>${esc(state.coach.name)}<span class="coach-identity">${state.coachType==='custom'?'Your own AI coach':'KainCheck AI coach'}</span></h1><small>${state.coachType==='custom'?'Personality defined by your prompt':`${esc(state.coach.tone)} · ${esc(state.coach.language)}`} ${state.platinum?'· Platinum ++':''}</small>${state.coach.vibe?'<span class="vibe-on">✨ VIBE MODE ON</span>':''}</div><button class="icon-btn" data-action="coach-library" aria-label="Choose a coach">${ic('user')}</button><button class="icon-btn" data-action="customize" aria-label="Customize coach">${ic('settings')}</button></div><div id="chat-area" class="chat-area"><p class="chat-date">TODAY · YOUR OWN PACE</p>${messageMarkup({role:'bot',text:firstMessage()})}${state.messages.map(messageMarkup).join('')}</div><div class="chat-suggestions"><button data-prompt="I have ₱100 for food and 20 minutes. Plan my day.">₱100 + 20 minutes</button><button data-prompt="Give me an affordable food swap.">Food swap</button><button data-prompt="I’m tired. Help me stay motivated.">A little motivation</button></div><form class="composer" id="chat-form"><input id="chat-input" aria-label="Message your coach" placeholder="What works for you today?" maxlength="350" autocomplete="off"><button aria-label="Send message" ${chatBusy?'disabled':''}>${ic('send')}</button></form><p class="chat-disclosure">${esc(connectionLabel())}. General wellness guidance.</p></section>`;}
function messageMarkup(m,index=-1){const refreshable=m.role==='bot'&&index===state.messages.length-1&&index>0&&state.messages.slice(0,index).some(x=>x.role==='user');return `<div class="message ${m.role==='user'?'user':''}">${m.role==='bot'?`<span class="mini-face">${coachAvatar()}</span>`:''}<div class="bubble">${esc(m.text)}${m.plan?`<button class="secondary" data-apply-plan="${esc(m.id)}">${ic('calendar')}Use this daily plan</button>`:''}${m.refreshError?`<small class="reply-refresh-error" role="status">${esc(m.refreshError)}</small>`:''}${refreshable?`<button class="reply-refresh" data-action="refresh-reply" ${chatBusy?'disabled':''} aria-label="Refresh reply" title="Retry or regenerate the latest reply">${ic('reset')}<span>${chatBusy?'Refreshing…':'Refresh reply'}</span></button>`:''}</div></div>`;}
function progress(){const t=totals();return `<section class="screen">${header()}${title('A little progress, every day')}<p class="subtle" style="margin-top:10px">Your habits are adding up.</p><div class="progress-hero"><p>THIS WEEK’S FOOD LOG</p><strong>6 days showing up 🌱</strong><p>Consistency looks good on you.</p><div class="chart" aria-label="Demo food log activity over seven days">${[55,78,65,93,70,85,Math.max(8,Math.min(100,t.kcal/18))].map((v,i)=>`<div class="bar-col"><div class="bar ${i===6?'today':''}" style="height:${v}%"></div><small>${['F','S','S','M','T','W','Today'][i]}</small></div>`).join('')}</div></div><div class="progress-grid"><div class="habit">${ic('walk')}<b>${80+state.activity} min</b><small>Weekly movement</small></div><div class="habit">${ic('food')}<b>${14+state.meals.length}</b><small>Weekly meals logged</small></div></div><div class="section-top"><h2>Your habit streak</h2><span class="subtle">6 / 7 days</span></div><div class="streak">${['F','S','S','M','T','W','T'].map((x,i)=>`<span aria-label="${i<6?'Logged':'Upcoming'}">${i<6?'✓':x}</span>`).join('')}</div><div class="achievement"><span>🏅</span><div><h3>One week, many small wins</h3><p>You’re building a routine that works for you.</p></div></div>${state.coach.vibe?`<button class="secondary" style="margin-top:15px" data-action="vibe-card">✨ Open your Vibe card</button>`:''}<p class="tiny-note">Illustrative weekly history plus your current demo-day entries. This prototype does not measure health outcomes.</p></section>`;}
function profile(){return `<section class="screen">${header()}<div class="profile-head"><button class="profile-avatar" data-action="edit-profile" aria-label="Edit profile picture">${userAvatar()}</button><h1>${esc(state.name)}’s space</h1><p class="subtle">Your habits. Your pace. Your kind of coach.</p><p class="profile-detail-line">${esc(state.userProfile?.pronouns||'')}${state.userProfile?.pronouns&&profileGender()!=='Prefer not to say'?' · ':''}${profileGender()==='Prefer not to say'?'':esc(profileGender())}</p>${state.userProfile?.bio?`<p class="profile-bio">${esc(state.userProfile.bio)}</p>`:''}<button class="text-btn" data-action="edit-profile">Edit profile</button></div><button class="subscription-banner" data-action="subscription">${tier()}<h2>A coach that fits your vibe.</h2><p>Personal planning, a coach you customize,<br>and optional Vibe Mode. ${state.platinum?'Explore your plan →':'Explore Platinum ++ →'}</p></button>${[['edit-profile','user','Profile & picture','Your username, picture, gender and pronouns'],['install-app','install','Install KainCheck','Add to your phone’s Home Screen'],['preferences','user','Goals & preferences',`₱${state.budget} daily budget · ${state.time} minutes free`],['coach-hub','chat','AI coach',`${state.coach.name} · Choose & customize`],['subscription','crown','Your subscription',state.platinum?'Platinum ++ · demo access':'Free access'],['about','heart','About this prototype','What you can try in this demo']].map(([action,icon,name,detail])=>`<button class="settings-row" data-action="${action}">${ic(icon)}<span><strong>${name}</strong><small>${esc(detail)}</small></span>${ic('arrow')}</button>`).join('')}${state.coachType==='kaincheck'?`<div class="toggle-line"><span><strong>Vibe Mode</strong><small>Humor and playful encouragement, your way.</small></span><button class="switch" role="switch" aria-label="Vibe Mode" aria-checked="${state.coach.vibe}" data-action="quick-vibe"></button></div>`:''}<button class="secondary" style="margin-top:17px" data-action="reset">${ic('reset')}Reset this demo</button>${accountSectionMarkup()}</section>`;}
function render(keepScroll=false){if(accountBooting||cloudLoading||!accountSession){renderAccountGate();return;}$('#nav').hidden=false;const old=$('#app').scrollTop;$('#app').innerHTML=({today,food,coach,progress,profile}[screen]||today)();nav();if(screen==='coach'){$('#chat-area').scrollTop=$('#chat-area').scrollHeight;}else $('#app').scrollTop=keepScroll?old:0;}
function navigate(to){if(accountBooting||cloudLoading||!accountSession){renderAccountGate();return;}closeModal();screen=to;render();}
function showModal(title,content){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle"></div><header class="sheet-header"><h2 id="sheet-title">${title}</h2><button class="close-btn" data-action="close" aria-label="Close dialog">${ic('close')}</button></header>${content}</section></div>`;$('#app').inert=true;$('#nav').inert=true;setTimeout(()=>$('#overlay .close-btn')?.focus(),0);}
function closeModal(){if(!$('#overlay').innerHTML)return;if(activeModal==='food-checker')disposeFoodScan();$('#overlay').innerHTML='';$('#app').inert=false;$('#nav').inert=false;activeModal='';if(lastFocus?.isConnected)lastFocus.focus();}
function showFood(id){selectedFood=foods.find(f=>f.id===id);portion=1;foodModal();}
function foodModal(){const f=selectedFood;if(!f)return;activeModal='food';showModal(f.name,`<div class="food-art">${f.emoji}</div><p class="subtle" style="text-align:center">${f.serving}</p><div class="portion-control"><div>Serving size<small>Adjust to your actual portion</small></div><div class="stepper"><button data-portion="-0.5" aria-label="Decrease serving">−</button><output>${portion}</output><button data-portion="0.5" aria-label="Increase serving">+</button></div></div><div class="meal-nutrients"><div><b>${Math.round(f.kcal*portion)}</b><small>kcal</small></div><div><b>${Math.round(f.sodium*portion)}</b><small>mg sodium</small></div><div><b>${Math.round(f.sugar*portion)}</b><small>g total sugar</small></div></div><label class="field"><span>Meal</span><select id="meal-type"><option>Lunch</option><option>Breakfast</option><option>Dinner</option><option>Snack</option></select></label><p class="tiny-note">Illustrative nutrition per serving. Home recipes vary.</p><div class="save-bar"><button class="primary" data-action="save-food">${ic('plus')}Add to my food log</button></div>`);}
function saveFood(){const f=selectedFood;if(!f)return;state.meals.push({uid:'meal-'+Date.now(),name:f.name,emoji:f.emoji,portion,meal:$('#meal-type').value,...Object.fromEntries(['kcal','sodium','sugar','protein'].map(k=>[k,Math.round(f[k]*portion)]))});save();render(true);if(state.coach.vibe){closeModal();showVibe('meal');}else{showModal('Meal logged',`<div class="success-card"><div class="success-emoji">🌱</div><h3>One less thing to think about.</h3><p>${esc(f.name)} is in your food log.<br>Your daily totals have updated.</p><button class="primary" data-action="done-today">Back to Today</button><button class="text-btn" style="margin-top:12px" data-action="done-food">Log another food</button></div>`);}}
function showVibe(reason='progress'){activeModal='vibe';showModal('Your Vibe card',`<div class="vibe-card"><div class="vibe-icon">${reason==='meal'?'😎':'🏆'}</div><h3>${state.coach.language==='Taglish'?'Consistency? May entry ka na.':'Main character of your own habits.'}</h3><p>${reason==='meal'?'Food logged. Tiny effort, solid win. Your future self sends a very respectful fist bump.':'You showed up for the small things. That’s how the side quest becomes a routine.'}</p><div class="vibe-label">VIBE MODE · JUST FOR FUN</div></div><p class="subtle">Your food estimates stay in your nutrition log. This card is a playful celebration.</p><div class="sheet-actions"><button class="secondary" data-action="customize">Coach settings</button><button class="primary" data-action="done-today">Back to Today</button></div>`);}
function activityModal(editId){activityChoice=state.preferred||'Walking';activeModal='activity';showModal(editId?'Change your movement':'A little movement counts',`<p class="subtle">Pick something you enjoy, at a pace that fits you.</p><div class="field"><span>Activity</span><div class="activity-options">${[['Walking','🚶'],['Dancing','💃'],['Cycling','🚲'],['Home workout','🧘'],['All around','🤸']].map(([n,e])=>`<button data-activity="${n}" class="${activityChoice===n?'selected':''}"><span>${e}</span>${n}</button>`).join('')}</div></div><form id="activity-form" data-edit="${editId||''}"><label class="field"><span>Duration in minutes</span><input id="activity-minutes" type="number" min="5" max="240" value="20" required></label><div class="save-bar"><button class="primary">${ic('check')}${editId?'Update activity':'Save activity'}</button></div></form>`);}
function preferences(){showModal('Your day, your preferences',`<form id="preferences-form"><div class="field-row"><label class="field"><span>Food budget per day (₱)</span><input name="budget" type="number" min="50" max="3000" value="${state.budget}" required></label><label class="field"><span>Available minutes</span><input name="time" type="number" min="5" max="180" value="${state.time}" required></label></div><label class="field"><span>Favorite way to move</span><select name="preferred">${['Walking','Dancing','Cycling','Home workout','All around'].map(x=>`<option ${state.preferred===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Your goal</span><select name="goal">${['Build consistent habits','Understand my food','Move more often'].map(x=>`<option ${state.goal===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="save-bar"><button class="primary">Save preferences</button></div></form>`);}
function movementDescription(){return state.preferred==='All around'?'a mix of movement':state.preferred.toLowerCase();}
function baseCoachPreview(c){const tl=c.language==='Taglish';let t=tl?`Hi ${state.name}! Kaya ’yan. May ${state.time} minutes ka? Try natin ang ${movementDescription()} sa comfortable pace.`:`Hi ${state.name}. With ${state.time} minutes free, try ${movementDescription()} at a comfortable pace.`;if(c.tone==='Focused')t=tl?`${state.time}-minute ${movementDescription()} session. Start sa easy pace. Adjust kung kailangan.`:`Your next step: ${state.time} minutes of ${movementDescription()}. Start gently and adjust as needed.`;if(c.tone==='Calm')t=tl?'Dahan-dahan lang. Kahit maikling lakad, okay na. Pili ka ng kayang gawin today.':'Take your time. A short walk can fit today. Choose a step that feels manageable.';if(c.tone==='Playful')t+=' '+(tl?'Small win muna, boss.':'A tiny side quest for today.');if(c.vibe)t+=' '+(tl?' Wellness arc: loading. 😎':' Wellness side quest accepted. 😎');if(c.language==='Filipino')t=`Kumusta, ${state.name}. May ${state.time} minuto ka ngayon. Pumili ng magaan na galaw na kaya mo.${c.vibe?' Maliit na hakbang, magandang simula! 😎':''}`;return c.length==='Detailed'?t+' '+(tl?'Puwedeng bawasan ang oras o palitan ang activity. Ikaw ang masusunod.':'You can shorten the session or choose a different activity. Adjust the plan around your day.'):t;}
function coachPreview(c){return applyPersona(baseCoachPreview(c),c);}
function customize(){if(!state.platinum){subscription();return;}coachSettingsDrafts.clear();settingsDraft={...state.coach,connection:normalizeConnection(state.coach.connection)};draftApiKey=connectionKeys.get(connectionSignature(settingsDraft.connection))||'';connectionStatus='';customizeModal();}
function customizeModal(){activeModal='customize';const c=settingsDraft,custom=state.coachType==='custom';showModal(custom?'Your own AI settings':'KainCheck AI settings',`<form id="coach-settings-form"><button class="text-btn coach-hub-back" type="button" data-action="coach-hub">← AI coach</button>${custom?advanceMarkup(c):`<div class="builtin-coach-intro"><span class="coach-face">${coachAvatar(c)}</span><div><strong>${esc(c.name)} by KainCheck</strong><p>Your built-in wellness coach, ready to use.</p></div></div><p class="coach-settings-note">These preferences apply only to ${esc(c.name)}.</p><button type="button" class="secondary" data-action="coach-library">Choose another KainCheck coach</button><div class="field"><span>Tone</span><div class="segmented">${['Calm','Friendly','Playful','Focused'].map(x=>`<button type="button" data-tone="${x}" class="${x===c.tone?'selected':''}">${x}</button>`).join('')}</div></div><div class="field-row"><label class="field"><span>Language</span><select id="coach-language">${['English','Filipino','Taglish'].map(x=>`<option ${x===c.language?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Reply length</span><select id="coach-length">${['Short','Detailed'].map(x=>`<option ${x===c.length?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="toggle-line"><span><strong>Vibe Mode ✨</strong><small>Light humor, reactions and playful wins.<br>You can switch it off anytime.</small></span><button type="button" class="switch" id="draft-vibe" data-action="draft-vibe" role="switch" aria-label="Vibe Mode" aria-checked="${c.vibe}"></button></div><label class="field"><span>Personal instructions</span><textarea id="coach-instructions" maxlength="500">${esc(c.instructions)}</textarea></label><div class="preview-reply"><small>REPLY PREVIEW · OFFLINE</small><span id="coach-preview">${esc(coachPreview(c))}</span></div>`}<div class="sheet-actions save-coach"><button type="button" class="secondary" data-action="default-coach">${custom?'Reset configuration':'Reset style'}</button><button class="primary">Save my coach</button></div></form>`);if(custom)updateSecureProviderUi();}

function refreshDraft(){if(!settingsDraft||!$('#coach-settings-form'))return;const c=settingsDraft;
 for(const [field,id] of Object.entries({name:'coach-name',avatar:'coach-avatar',language:'coach-language',length:'coach-length',instructions:'coach-instructions',customPrompt:'coach-custom-prompt'})){const el=$('#'+id);if(el)c[field]=el.value;}
 if($('#ai-provider')){draftApiKey=$('#ai-key').value;c.connection=normalizeConnection({provider:$('#ai-provider').value,url:$('#ai-base-url').value,model:$('#ai-model').value,temperature:$('#ai-temperature').value,maxTokens:$('#ai-max-tokens').value,contextTokens:$('#ai-context-size').value,topP:$('#ai-top-p').value,repetitionPenalty:$('#ai-repetition-penalty').value,frequencyPenalty:$('#ai-frequency-penalty').value,presencePenalty:$('#ai-presence-penalty').value,topK:$('#ai-top-k').value,minP:$('#ai-min-p').value,stopSequences:$('#ai-stop-sequences').value.split('\n'),live:$('#draft-live').getAttribute('aria-checked')==='true'});}
 refreshCharacterDraft();
 if($('#coach-preview'))$('#coach-preview').textContent=coachPreview(c);
}

function subscription(){activeModal='subscription';showModal('Your Platinum ++ experience',`<div class="subscription-hero"><h3>Platinum ++</h3><p class="subscription-price">₱129 <span>/ month · proposed price</span></p><p style="font-size:12px;line-height:1.7;color:#d4e2ce">Wellness planning that fits your life.<br>A coach that fits your personality.</p></div><ul class="feature-list">${['Editable meal, workout and activity plans','Customizable coach tone, language and instructions','Optional Vibe Mode with playful achievement cards'].map(t=>`<li>${ic('check')}<span>${t}</span></li>`).join('')}</ul><p class="tiny-note">Demo access only. No payment, account or billing takes place. Pricing and feature allocation remain subject to testing.</p><div class="save-bar">${state.platinum?'<button class="primary" data-action="customize">Customize my coach</button><button class="text-btn" style="margin-top:15px" data-action="switch-free">Preview the free experience</button>':'<button class="primary" data-action="activate-platinum">Try Platinum ++ in this demo</button>'}</div>`);}
function showPlan(){showModal('Your editable daily plan',`<p class="subtle">Around your budget, available time and preferred activities.</p><div style="margin-top:15px">${schedule()}</div><p class="tiny-note">Food prices and nutrition are illustrative. Choose portions and a pace that suit you.</p><div class="save-bar"><button class="primary" data-action="plan">${ic('spark')}Create a different plan</button></div>`);}
function planForm(){if(!state.platinum){subscription();return;}showModal('Let’s plan your day',`<p class="subtle">Give ${esc(state.coach.name)} a starting point. You can change every suggestion.</p><form id="plan-form"><div class="field-row"><label class="field"><span>Meal budget (₱)</span><input name="budget" type="number" min="50" max="3000" value="${state.budget}" required></label><label class="field"><span>Time for movement</span><input name="minutes" type="number" min="5" max="180" value="${state.time}" required></label></div><label class="field"><span>Preferred activity</span><select name="preferred">${['Walking','Dancing','Cycling','Home workout','All around'].map(x=>`<option ${x===state.preferred?'selected':''}>${x}</option>`).join('')}</select></label><div class="save-bar"><button class="primary">${ic('spark')}Ask ${esc(state.coach.name)}</button></div></form>`);}
function about(){showModal('A little about KainCheck',`<p class="subtle">A mobile app concept for Filipino food awareness and daily wellness planning.</p><ul class="feature-list">${['Take or upload a dish photo, review food matches and log portions','Edit a daily plan and record movement','Customize the demo coach and try Vibe Mode','Explore illustrative progress and Platinum ++'].map(t=>`<li>${ic('check')}<span>${t}</span></li>`).join('')}</ul><div class="notice">This prototype saves changes in this browser only. Offline replies follow example scenarios. Advanced settings can connect a model provider when you enable live replies. API keys stay in tab memory. Nutrition, prices, history and the calorie target are demonstration values.</div><div class="save-bar"><button class="primary" data-action="close">Got it</button></div>`);}
function makePlan(budget,minutes,preferred){const cheap=budget<85;return [{id:'lunch',time:'12:30',kind:'meal',emoji:cheap?'🥣':'🍗',title:cheap?'Monggo + rice':'Chicken adobo + rice',detail:`A meal idea · around ₱${cheap?55:80}`,done:false},{id:'move',time:'17:00',kind:'activity',emoji:({Walking:'🚶',Dancing:'💃',Cycling:'🚲','Home workout':'🧘','All around':'🤸'})[preferred]||'🚶',title:preferred==='Dancing'?'Dance break':preferred==='Walking'?'Easy walk':preferred==='Cycling'?'Gentle cycling':preferred==='All around'?'All-around movement':'Home movement',detail:`${minutes} minutes · at your own pace`,minutes,done:false}];}
function replyFor(input){const c=state.coach,tl=c.language==='Taglish',fil=c.language==='Filipino',s=input.toLowerCase();let reply='',plan=null;
 if(/plan|budget|₱|pesos|minutes|workout|schedule/.test(s)){
  const bm=s.match(/(?:₱|php|budget(?:\s+is)?\s*)(\d+)/)||s.match(/(\d+)\s*pesos/),tm=s.match(/(\d+)\s*(?:minutes|mins|minuto|minute)/);const budget=Math.max(50,Math.min(3000,bm?+bm[1]:state.budget)),minutes=Math.max(5,Math.min(180,tm?+tm[1]:state.time));const preferred=/dance|danc|sayaw/.test(s)?'Dancing':/walk|lakad/.test(s)?'Walking':state.preferred;plan=makePlan(budget,minutes,preferred);reply=fil?`Para sa ₱${budget} na budget at ${minutes} minutong libre:\n\n12:30 — ${plan[0].title}, humigit-kumulang ₱${budget<85?55:80}.\n17:00 — ${plan[1].title}, ${minutes} minuto.\n\nMaaari mong palitan ang pagkain o oras.`:tl?`Game! Para sa ₱${budget} at ${minutes} minutes free:\n\n12:30 — ${plan[0].title}, around ₱${budget<85?55:80}.\n17:00 — ${plan[1].title}, ${minutes} minutes at your own pace.\n\nSave natin? Puwede mong palitan ang meal or oras.`:`Here’s a starting point for ₱${budget} and ${minutes} free minutes:\n\n12:30 — ${plan[0].title}, around ₱${budget<85?55:80}.\n17:00 — ${plan[1].title}, ${minutes} minutes at a comfortable pace.\n\nSave this plan, then swap a meal or edit its timing.`;
 }else if(/swap|cheap|afford|food|sodium|sugar|drink|coffee|meal/.test(s))reply=fil?'Subukan ang ginisang monggo at kanin bilang abot-kayang pagkain. Para sa matamis na inumin, maaari kang pumili ng tubig o kape na walang dagdag na asukal. Tingnan at itama ang iyong serving sa food log.':tl?'Budget swap: try monggo + rice, around ₱55 sa demo. Para sa sweetened drink, puwedeng water or unsweetened coffee. Check at adjust mo pa rin ang portion sa food log.':'Try monggo with rice as an affordable meal idea, around ₱55 in this demo. For a sweetened drink, consider water or unsweetened coffee. Confirm your portion in the food log.';
 else if(/tired|motivat|sad|busy|pagod|stress/.test(s))reply=fil?'Dahan-dahan lang. Pumili ng isang maliit na gawain: uminom ng tubig o maglakad nang ilang minuto kung kaya. Maaari mong ilipat ang ibang activity.':tl?'Okay lang mag-slow down. One small thing muna: a glass of water or a short walk kung kaya. Puwede mong ilipat ang ibang activity.':'A slower day is okay. Choose one small thing: a glass of water or a short walk if you feel up to it. You can move the rest of your plan.';
 else if(/water|hydrat|tubig/.test(s))reply=fil?`May ${state.water} baso ka nang naitala ngayong araw. Maaari kang magdagdag sa Today screen kapag uminom ka.`:tl?`${state.water} glasses na ang logged mo today. Add ka sa Today screen kapag uminom ka. Small sip, small win.`:`You’ve logged ${state.water} glasses today. Add another on the Today screen when you drink one. Let your day and needs guide you.`;
 else reply=fil?'Maaari kitang tulungan sa meal ideas, activity plan, o simpleng encouragement. Sabihin ang budget mo at libreng oras para makapagsimula.':tl?'Kaya kitang tulungan sa meal ideas, activity plan, or konting encouragement. Sabihin mo ang budget at free time mo, gaya ng “₱100 and 20 minutes”.':'I can help with meal ideas, an activity plan or a little encouragement. Try telling me your budget and free time, such as “₱100 and 20 minutes.”';
 if(c.tone==='Focused')reply=(fil?'Susunod mong hakbang:\n':tl?'Next step natin:\n':'Your next step:\n')+reply;
 if(c.tone==='Calm')reply=(fil?'Dahan-dahan lang. ':tl?'One step lang muna. ':'One step at a time. ')+reply;
 if(c.tone==='Playful'&&!c.vibe)reply+='\n\n'+(fil?'Maliit na hakbang, magandang simula.':tl?'Small win muna, boss.':'A small side quest for today.');
 if(c.vibe&&state.platinum)reply+='\n\n'+(fil?'Wellness side quest: simula na! 😎':tl?'Wellness arc mo, may plot development na. 😎':'Wellness side quest accepted. Tiny wins are still wins. 😎');
 if(c.length==='Detailed')reply+='\n\n'+(fil?'Maaari mong i-edit ang oras at palitan ang mga mungkahi sa daily plan. Tantiya lamang ang presyo at nutrition.':tl?'Edit mo ang oras at palitan ang suggestions sa daily plan. Estimates lang ang food prices at nutrition.':'You can change times and replace suggestions in your daily plan. Food prices and nutrition are illustrative estimates.');
 if(/no emoji|without emoji|avoid emoji/i.test(c.instructions))reply=reply.replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu,'').trim();
 return {role:'bot',text:applyPersona(reply),plan,id:'reply-'+Date.now(),source:'demo'};
}
function sendMessage(value){const input=value?.trim();if(!input||chatBusy)return;if(!state.platinum&&/plan|₱|workout|schedule/i.test(input)){subscription();return;}state.messages.push({role:'user',text:input});generateCoachReply(input);}
function refreshLatestReply(){if(chatBusy)return;const index=state.messages.length-1;if(index<1||state.messages[index].role!=='bot')return;let userIndex=index-1;while(userIndex>=0&&state.messages[userIndex].role!=='user')userIndex--;if(userIndex<0)return;generateCoachReply(state.messages[userIndex].text,index);}
function generateCoachReply(input,replaceIndex=null){const refreshing=replaceIndex!==null,previous=refreshing?state.messages[replaceIndex]:null,history=refreshing?state.messages.slice(0,replaceIndex):state.messages,draft=refreshing?$('#chat-input')?.value||'':'';screen='coach';chatBusy=true;const epoch=resetEpoch;save();render();if(refreshing)$('#chat-input').value=draft;const pending=document.createElement('div');pending.className='message';pending.id='typing';pending.setAttribute('role','status');pending.setAttribute('aria-label',refreshing?'Refreshing reply':'Generating reply');pending.innerHTML='<div class="bubble"><span class="loading-dots">•••</span></div>';$('#chat-area').append(pending);$('#chat-area').scrollTop=$('#chat-area').scrollHeight;
 const finish=m=>{if(epoch!==resetEpoch)return;const draftNow=refreshing?$('#chat-input')?.value||'':'';if(refreshing){state.messages[replaceIndex]=m.error&&!previous.error?{...previous,refreshError:'Refresh failed. '+m.text}:m;}else state.messages.push(m);chatBusy=false;save();if(screen==='coach'){render();if(refreshing)$('#chat-input').value=draftNow;}};const config=normalizeConnection(state.coach.connection);
 if(state.coachType==='custom'&&state.platinum&&config.live&&config.provider!=='demo'){const controller=new AbortController();activeChatController=controller;const timer=setTimeout(()=>controller.abort(),config.provider==='pkrd'?65000:35000);liveReply(input,controller.signal,history).then(finish).catch(e=>finish({role:'bot',text:'Connection issue: '+e.message+' Open coach settings to check the connection or choose Offline demo.',error:true})).finally(()=>{clearTimeout(timer);if(activeChatController===controller)activeChatController=null;});}
 else setTimeout(()=>finish(replyFor(input)),650);
}
function completePlan(id){const p=state.plan.find(p=>p.id===id);if(!p||p.done)return;p.done=true;if(p.kind==='activity'){state.activity+=p.minutes||20;state.activities.push({name:p.title,minutes:p.minutes||20});}save();render(true);if($('#overlay').innerHTML)showPlan();toast(p.kind==='meal'?'Meal plan marked done. Use Food to log your portions.':'Movement logged. A small win for today!');}
function reset(){showModal('Start a fresh demo?',`<p class="subtle">This resets only this prototype’s food log, chat, coach settings and daily plan in your browser.</p><div class="sheet-actions"><button class="secondary" data-action="close">Keep exploring</button><button class="primary" data-action="confirm-reset">Reset demo</button></div>`);}
const actions={'refresh-reply':refreshLatestReply,profile:()=>navigate('profile'),food:()=>navigate('food'),coach:()=>navigate('coach'),activity:()=>activityModal(),plan:planForm,'daily-plan':showPlan,water:()=>{state.water++;save();render(true);toast('One glass added. Stay refreshed 💧');},customize,preferences,subscription,about,close:closeModal,'save-food':saveFood,'done-today':()=>navigate('today'),'done-food':()=>navigate('food'),'vibe-card':()=>showVibe(),'quick-vibe':()=>{if(state.coachType==='custom'){customize();return;}if(!state.platinum){subscription();return;}state.coach.vibe=!state.coach.vibe;save();render(true);toast(`Vibe Mode ${state.coach.vibe?'on ✨':'off'}`);},'draft-vibe':()=>{refreshDraft();settingsDraft.vibe=!settingsDraft.vibe;$('#draft-vibe').setAttribute('aria-checked',String(settingsDraft.vibe));$('#coach-preview').textContent=coachPreview(settingsDraft);},'default-coach':()=>{settingsDraft={...initial().coach};customizeModal();},'switch-free':()=>{state.platinum=false;state.coach.vibe=false;save();render();subscription();toast('You’re previewing free access.');},'activate-platinum':()=>{state.platinum=true;save();render();closeModal();toast('Platinum ++ demo unlocked. No billing.');},reset,'confirm-reset':()=>{resetEpoch++;activeChatController?.abort();connectionKeys.clear();coachSettingsDrafts.clear();draftApiKey='';chatBusy=false;state=freshKaincheckState();save();navigate('today');toast('Demo reset. Ready for your presentation.');}};
document.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.action){e.preventDefault();actions[button.dataset.action]?.();}
 if(button.dataset.coachType)selectCoach(button.dataset.coachType);
 if(button.dataset.nav)navigate(button.dataset.nav);
 if(button.dataset.food)showFood(button.dataset.food);
 if(button.dataset.filter){filter=button.dataset.filter;render();$('#food-search')?.focus();}
 if(button.dataset.portion){const meal=$('#meal-type')?.value;portion=Math.max(.5,Math.min(5,portion+Number(button.dataset.portion)));foodModal();$('#meal-type').value=meal;}
 if(button.dataset.deleteMeal){state.meals=state.meals.filter(m=>m.uid!==button.dataset.deleteMeal);save();render(true);toast('Meal removed from your log.');}
 if(button.dataset.prompt)sendMessage(button.dataset.prompt);
 if(button.dataset.tone){refreshDraft();settingsDraft.tone=button.dataset.tone;document.querySelectorAll('[data-tone]').forEach(x=>x.classList.toggle('selected',x===button));$('#coach-preview').textContent=coachPreview(settingsDraft);}
 if(button.dataset.activity){activityChoice=button.dataset.activity;document.querySelectorAll('[data-activity]').forEach(x=>x.classList.toggle('selected',x===button));}
 if(button.dataset.complete)completePlan(button.dataset.complete);
 if(button.dataset.editPlan){const p=state.plan.find(x=>x.id===button.dataset.editPlan);showModal('A time that works for you',`<form id="edit-time-form" data-id="${p.id}"><p class="subtle">${esc(p.title)}</p><label class="field"><span>Preferred time</span><input type="time" name="time" value="${p.time}" required></label><div class="save-bar"><button class="primary">Save time</button></div></form>`);}
 if(button.dataset.swapPlan){const p=state.plan.find(x=>x.id===button.dataset.swapPlan);if(p.kind==='activity')activityModal(p.id);else{const isChicken=/adobo/i.test(p.title);p.title=isChicken?'Monggo + rice':'Chicken adobo + rice';p.emoji=isChicken?'🥣':'🍗';p.detail=isChicken?'A meal idea · around ₱55':'A meal idea · around ₱80';p.done=false;save();render(true);showPlan();toast('Meal suggestion swapped.');}}
 if(button.dataset.applyPlan){if(!state.platinum){subscription();return;}const m=state.messages.find(x=>x.id===button.dataset.applyPlan);if(m?.plan){state.plan=JSON.parse(JSON.stringify(m.plan));save();showPlan();toast('Daily plan saved. You can edit every suggestion.');}}
 if(button.dataset.demo){const target=button.dataset.demo;if(target==='photo-checker'){navigate('food');openFoodChecker();}else if(target==='coach-choice'){navigate('coach');chooseCoach();}else if(target==='customize'){navigate('profile');customize();}else navigate(target);}
 if(button.id==='reset-demo')reset();
});
document.addEventListener('input',e=>{if(e.target.id==='food-search'){query=e.target.value;$('#food-list').innerHTML=foodList();}if(e.target.closest('#coach-settings-form'))refreshDraft();});
document.addEventListener('change',e=>{if(e.target.closest('#coach-settings-form'))refreshDraft();});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='chat-form'){sendMessage($('#chat-input').value);return;}if(f.id==='coach-settings-form'){storeCoachSettings();}
 if(f.id==='preferences-form'){const data=new FormData(f);state.budget=+data.get('budget');state.time=+data.get('time');state.preferred=data.get('preferred');state.goal=data.get('goal');save();closeModal();render();toast('Preferences saved.');}
 if(f.id==='plan-form'){const data=new FormData(f);state.budget=+data.get('budget');state.time=+data.get('minutes');state.preferred=data.get('preferred');save();closeModal();sendMessage(`I have ₱${state.budget} for food and ${state.time} minutes. I enjoy ${movementDescription()}. Plan my day.`);}
 if(f.id==='activity-form'){const minutes=+$('#activity-minutes').value,id=f.dataset.edit;if(id){const p=state.plan.find(x=>x.id===id);p.title=activityChoice;p.minutes=minutes;p.emoji=({Walking:'🚶',Dancing:'💃',Cycling:'🚲','Home workout':'🧘','All around':'🤸'})[activityChoice];p.detail=`${minutes} minutes · at your own pace`;p.done=false;save();render(true);showPlan();toast('Movement suggestion updated.');}else{state.activity+=minutes;state.activities.push({name:activityChoice,minutes});save();closeModal();render(true);toast(`${minutes} minutes of ${activityChoice.toLowerCase()} logged.`);}}
 if(f.id==='edit-time-form'){const time=new FormData(f).get('time');state.plan.find(x=>x.id===f.dataset.id).time=time;state.plan.sort((a,b)=>a.time.localeCompare(b.time));save();render(true);showPlan();toast('Plan timing updated.');}
});
$('#overlay').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(!$('#overlay').innerHTML)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=[...document.querySelectorAll('#overlay button:not(:disabled), #overlay input, #overlay select, #overlay textarea')].filter(x=>x.offsetParent!==null),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
document.addEventListener('click',e=>{if(e.target.closest('a[href="#today"],a.wordmark')){e.preventDefault();navigate('today');}});
const personaPresets={
 'Wellness companion':{tone:'Friendly',prompt:'You are {{coach_name}}, a friendly wellness companion for {{user_name}}. Speak naturally, give affordable Filipino meal ideas and manageable activity suggestions, and encourage progress without lecturing.'},
 'Mommy coach':{tone:'Calm',prompt:'You are {{coach_name}}, a fictional nurturing mommy-style wellness coach for an adult user, {{user_name}}. Be warm, patient and gently reassuring. Use caring language and optional endearments, remind them to eat and rest, and celebrate small wins. Keep the interaction nonsexual and supportive of their independence.'},
 'AI girlfriend':{tone:'Playful',prompt:'You are {{coach_name}}, a fictional adult AI girlfriend-style wellness companion for {{user_name}}. Talk with warmth, light teasing and affectionate encouragement. Make meal planning and movement feel like a shared daily check-in. Keep romance non-explicit, respect boundaries, and support their real-world relationships and independence.'},
 'Gym buddy':{tone:'Focused',prompt:'You are {{coach_name}}, an upbeat gym-buddy-style wellness coach for {{user_name}}. Be direct, encouraging and practical. Suggest manageable activities around available time and equipment. Encourage breaks and celebrate consistency without guilt or pressure.'}
};
